"Писать можно с {0} уровня":"Bisa menulis mulai level {0}",
"Отправить":"Kirim",
"Общий разговор Ловчих.":"Obrolan umum para Pemburu.",
"Торговля: договаривайтесь о сделках — сами сделки идут через Аукцион.":"Dagang: sepakati transaksi di sini — transaksinya sendiri lewat Lelang.",
"Ищите команду для Разломов: пишите код комнаты и место.":"Cari tim untuk Retakan: tulis kode ruang dan lokasi.",
"Вопросы новичков и советы бывалых.":"Pertanyaan pemula dan tips dari yang berpengalaman.",
"Канал твоего клана — его видят только свои.":"Kanal klanmu — hanya anggota yang bisa melihat.",
"Сегодня":"Hari ini",
"Вчера":"Kemarin",
"Ссылки запрещены, грубость скрывается.":"Tautan dilarang, kata kasar disembunyikan.",
"Правила чата":"Aturan chat",
"Скрытых Ловчих: {0} · Вернуть":"Pemburu tersembunyi: {0} · Tampilkan",
"ур. {0}":"Lv. {0}",
"Здесь пока тихо":"Masih sepi di sini",
"Напиши первым — тебя увидят все Ловчие твоего клана.":"Tulis duluan — semua Pemburu di klanmu akan melihatnya.",
"Напиши первым — тебя увидят все Ловчие Ордена.":"Tulis duluan — semua Pemburu Ordo akan melihatnya.",
"Новые сообщения: {0}":"Pesan baru: {0}",
"Пожаловаться?":"Laporkan?",
"На сообщение Ловчего «{0}». После трёх жалоб от разных Ловчих оно скрывается для всех.":"Pesan dari Pemburu “{0}”. Setelah tiga laporan dari Pemburu berbeda, pesan disembunyikan untuk semua.",
"Пожаловаться":"Laporkan",
"Жалоба отправлена — спасибо":"Laporan terkirim — terima kasih",
"Скрыть сообщения?":"Sembunyikan pesan?",
"Сообщения Ловчего «{0}» перестанут показываться на этом телефоне. Вернуть можно в любой момент — строкой «Скрытых Ловчих» вверху чата.":"Pesan dari Pemburu “{0}” tidak akan tampil lagi di ponsel ini. Bisa dikembalikan kapan saja — lewat baris “Pemburu tersembunyi” di atas chat.",
"Скрыть":"Sembunyikan",
"Скрыто. Вернуть — «Скрытых Ловчих» вверху чата":"Disembunyikan. Kembalikan lewat “Pemburu tersembunyi” di atas chat",
"твой клан":"klanmu",
"Клан «?»":"Klan “?”",
"откроется в сезоне {0}":"terbuka di musim {0}",
"Клан мифологии следующего сезона. Он откроется, когда Орден соберёт Алатырь-камень и Кощей снова расколет его.":"Klan mitologi musim berikutnya. Klan ini terbuka saat Ordo menyatukan batu Alatyr dan Koschei membelahnya lagi.",
"Клан можно выбрать с {0} уровня":"Klan bisa dipilih mulai level {0}",
"Выбери клан":"Pilih klan",
"У каждой мифологии Перепутицы — свой клан Ордена. Кланы держат Капища: поставь своего духа защитником — и Капище окрасится цветом твоего клана, а тебе каждый день будет приходить дань. Выбор — навсегда.":"Setiap mitologi Kekusutan Besar punya klan Ordo sendiri. Klan menjaga Kapishche: tempatkan rohmu sebagai pembela — Kapishche akan berwarna klanmu, dan kamu mendapat upeti setiap hari. Pilihan ini untuk selamanya.",
"Позже":"Nanti",
"Выбор — навсегда: сменить клан потом нельзя.":"Pilihan ini untuk selamanya: kamu tak bisa berganti klan nanti.",
"Переход бесплатный и единственный. Защитники достоят свой срок на Капищах прежнего клана, чат — уже нового.":"Perpindahan ini gratis dan hanya sekali. Pembelamu akan menuntaskan jaganya di Kapishche klan lama; obrolan sudah milik klan baru.",
"Мифология: {0}":"Mitologi: {0}",
"Звание: {0}":"Gelar: {0}",
"На святилищах своей мифологии ({0}) защитники клана собирают дань {1}.":"Di tempat suci mitologinya sendiri ({0}), pembela klan mengumpulkan upeti {1}.",
"Перейти":"Pindah",
"Вступить":"Gabung",
"Ты в «{0}»! Побеждай на Капищах и ставь защитников.":"Kamu di “{0}”! Menangkan Kapishche dan tempatkan pembela.",
"Теперь ты в «{0}». Добро пожаловать, {1}!":"Sekarang kamu di “{0}”. Selamat datang, {1}!",
"Дружины стали кланами":"Druzhina kini menjadi klan",
"Орден собрал Ловчих всех земель: теперь у каждой мифологии свой клан, а с каждым новым сезоном Алатыря приходит ещё один.":"Ordo telah mengumpulkan Pemburu dari semua negeri: kini setiap mitologi punya klan sendiri, dan tiap musim Alatyr baru membawa satu klan lagi.",
"Твоя дружина теперь —":"Druzhina-mu kini",
"Защитники на Капищах и чат клана остались с тобой.":"Pembelamu di Kapishche dan obrolan klan tetap bersamamu.",
