"Дух останется у тебя: на Капище встанет его отражение. Пока он стоит, раз в день приходит дань — ✦ {0} и оберег.":"Rohnya tetap milikmu: di Kapishche berdiri bayangannya. Selama dia berjaga, sehari sekali datang upeti — ✦ {0} dan jimat.",
"Отражение стоит до {0} суток: первые {1} ч в полной силе, потом устаёт и слабеет, а затем возвращается домой. Защитники — не больше чем на {2} Капищах.":"Pertahanan bertahan hingga {0} hari: {1} j pertama dengan kekuatan penuh, lalu lelah dan melemah, kemudian pulang. Pembela maks. di {2} Kapishche.",
