"Оберег":"Jimat",
"Узелок с заговорённой травой. Бросай в духа, чтобы поймать.":"Buntalan berisi ramuan bermantra. Lempar ke roh untuk menangkapnya.",
"Серебряный оберег":"Jimat perak",
"Серебро держит духов крепче. Шанс поимки ×1,5.":"Perak menahan roh lebih kuat. Peluang tangkap ×1,5.",
"Золотой оберег":"Jimat emas",
"Лучший оберег Ордена. Шанс поимки ×2.":"Jimat terbaik Ordo. Peluang tangkap ×2.",
"Духи обожают мёд. Успокаивает духа: шанс поимки ×1,5 на один бросок.":"Roh suka sekali madu. Menenangkan roh: peluang tangkap ×1,5 untuk satu lemparan.",
"Подорожник":"Daun sendok",
"Лист к ране — и полегчало. Возвращает духу четверть здоровья.":"Tempelkan daun di luka — langsung lega. Memulihkan seperempat HP roh.",
"Целебный отвар":"Ramuan penyembuh",
"Травы Велеса, сваренные в воде из источника. Возвращает духу 60% здоровья.":"Rempah Veles yang direbus dengan air mata air. Memulihkan 60% HP roh.",
"Мёртвая вода":"Myortvaya Voda",
"Редкая сказочная вода, что сращивает самые тяжкие раны. Дух без сил поднимется на 4 часа раньше. Живых не лечит.":"Air dongeng langka yang menyatukan luka terparah. Roh yang pingsan bangun 4 jam lebih cepat. Tak menyembuhkan roh yang masih berdiri.",
"Живая вода":"Zhivaya Voda",
"Возвращает духу половину здоровья, а в разломе — лечит прямо в бою. Духа без сил не поднимет.":"Mengembalikan separuh HP roh, dan di retakan — menyembuhkan langsung di pertarungan. Tak bisa membangunkan roh yang pingsan.",
"Ладан":"Dupa",
"Дымок приманивает духов: 30 минут их вокруг вдвое больше.":"Asapnya memikat roh: selama 30 menit roh di sekitarmu dua kali lebih banyak.",
"Дальний пропуск":"Tiket Jarak Jauh",
"Грамота Ордена: закрыть Разлом до 5 км от тебя, не подходя к нему. Один Орден дарит каждый день.":"Surat Ordo: tutup Retakan hingga 5 km darimu tanpa mendekat. Ordo memberi satu setiap hari.",
"Кольцо Ордена с воронкой дорог: шагни в любое место Атласа мира сразу, не дожидаясь перезарядки. Одни Врата дарят на седьмой день серии.":"Cincin Ordo dengan pusaran jalan: langsung melangkah ke tempat mana pun di Atlas Dunia tanpa menunggu jeda. Satu diberikan pada hari ketujuh beruntun.",
"Настой опыта":"Ramuan XP",
"Медовый настой на травах Велеса: сутки опыта на четверть больше.":"Ramuan madu dari herba Veles: sehari penuh XP seperempat lebih banyak.",
"Подарок":"Hadiah",
"Узелок для друга: обереги, мёд, иногда кокон. Отправляется в «Меню → Друзья», раз в день каждому.":"Buntalan untuk teman: jimat, madu, kadang kepompong. Dikirim di “Menu → Teman”, sehari sekali ke tiap teman.",
