"Европа":"Eropa",
"Здесь сходятся старые дороги Нави, Олимпа, Асгарда и холмов сидов — от Москвы до Дублина.":"Di sinilah jalan-jalan lama Nav, Olimpus, Asgard, dan bukit para sidhe bertemu — dari Moskwa sampai Dublin.",
"Азия":"Asia",
"От Уральских гор до Тихого океана. Отсюда родом небесные драконы Китая, а Сибирь и Средняя Азия — края славянских духов.":"Dari Pegunungan Ural sampai Samudra Pasifik. Naga langit Tiongkok berasal dari sini, sedangkan Siberia dan Asia Tengah adalah tanah roh Slavia.",
"Африка":"Afrika",
"Здесь, у Нила, стоят врата Дуата — родины египетских богов и духов пустыни.":"Di sini, di tepi Sungai Nil, berdiri gerbang Duat — rumah para dewa Mesir dan roh gurun.",
"Северная Америка":"Amerika Utara",
"Земля пернатых змеев: из долины Мехико вышли ацтекские боги и духи.":"Tanah ular berbulu: para dewa dan roh Aztek datang dari Lembah Meksiko.",
"Южная Америка":"Amerika Selatan",
"Сельва, Анды и Амазонка. Ацтекские духи разлетелись и сюда — до самой Огненной Земли.":"Hutan rimba, Andes, dan Amazon. Roh-roh Aztek juga terbang sampai ke sini — hingga Tierra del Fuego.",
"Австралия и Океания":"Australia dan Oseania",
"Своих мифологий у Ордена здесь пока нет: все духи Австралии и Океании — гости, которых занесла Перепутица.":"Ordo belum punya mitologi asli di sini: semua roh di Australia dan Oseania adalah tamu yang terbawa Kekusutan Besar.",
"Антарктида":"Antarktika",
"Здесь только пингвины и ледяные духи. Врата сюда не открываются — слишком холодно даже для Ловчих.":"Di sini hanya ada penguin dan roh es. Gerbang tidak terbuka ke sini — terlalu dingin, bahkan bagi Pemburu.",
"Миров духов всегда было много — у каждого народа свой: Навь у славян, царство Аида у греков, Асгард у скандинавов, холмы сидов у кельтов, Дуат у египтян, Небеса у китайцев, Миктлан у ацтеков. На местах их держал <b>Алатырь</b> — бел-горюч камень в середине всех миров. Каждые врата вели в свою землю, и духи не путали дорог.":"Dunia roh sejak dulu ada banyak — tiap bangsa punya sendiri: Nav milik bangsa Slavia, kerajaan Hades milik bangsa Yunani, Asgard milik bangsa Skandinavia, bukit peri milik bangsa Kelt, Duat milik bangsa Mesir, Langit milik bangsa Tiongkok, Mictlan milik bangsa Aztek. Semuanya dijaga tetap di tempatnya oleh <b>Alatyr</b>, batu putih membara di pusat semua dunia. Tiap gerbang menuju negerinya sendiri, dan roh tak pernah salah jalan.",
"Однажды осенней ночью Кощей Бессмертный решил спрятать свою смерть понадёжнее — прямо в сердце Алатыря. Камень треснул и раскололся. Все врата распахнулись разом, дороги между мирами спутались в клубок, и духи и боги семи мифологий высыпали в наш мир — кто куда. Эту ночь назвали <b>Перепутицей</b>. Кощей уверяет, что камень треснул сам, но Локи и Сунь Укун при этих словах почему-то хихикают.":"Suatu malam di musim gugur, Koschei yang Abadi memutuskan menyembunyikan kematiannya di tempat yang lebih aman — tepat di jantung Alatyr. Batu itu retak lalu terbelah. Semua gerbang terbuka sekaligus, jalan antardunia kusut seperti gulungan benang, dan roh serta dewa dari tujuh mitologi berhamburan ke dunia kita, ke segala arah. Malam itu disebut <b>Kekusutan Besar</b>. Koschei bersikeras batu itu retak sendiri, tapi entah kenapa Loki dan Sun Wukong cekikikan setiap kali dia bilang begitu.",
"Теперь Гиппокамп плещется в московском фонтане, Леший гуляет по токийскому парку, а Ниссе греет котов в подъездах Каира. Любого духа можно встретить в любом уголке земли. Разломы — трещины от расколотого камня — открываются в каждом городе, а боги ставят святилища там, где осели: Капище по соседству с Пагодой, Храм через улицу от Пирамиды. Город рождает и своих, новых духов: Вайфайку, Трамвайника, Фонарника.":"Kini Hippokampus bermain air di air mancur Moskow, Leshy berjalan-jalan di taman Tokyo, dan Nisse menghangatkan kucing di tangga apartemen Kairo. Roh apa pun bisa ditemui di setiap penjuru bumi. Retakan — celah sisa batu yang pecah — terbuka di setiap kota, dan para dewa mendirikan tempat suci di mana pun mereka menetap: Kapishche bersebelahan dengan Pagoda, Kuil di seberang jalan Piramida. Kota juga melahirkan roh barunya sendiri: Vayfayka, Tramvaynik, Fonarnik.",
"Первыми с гостями поладили не учёные, а бабушки со своими оберегами: оказалось, оберег, сделанный с заботой, успокаивает любого духа, откуда бы тот ни был. Так появился <b>Орден Оберега</b> — союз Ловчих всех земель. Твоя задача — находить духов, ловить их оберегами, черпать силу из источников, закрывать разломы и собирать осколки Алатыря. Кто знает — может, однажды их хватит, чтобы распутать дороги домой.":"Yang pertama akur dengan para tamu bukan ilmuwan, melainkan nenek-nenek dengan jimat mereka: ternyata jimat yang dibuat dengan kasih sayang menenangkan roh apa pun, dari mana pun asalnya. Begitulah lahir <b>Ordo Jimat</b> — persekutuan Pemburu dari semua negeri. Tugasmu: menemukan roh, menangkapnya dengan jimat, mengambil tenaga dari sumber, menutup retakan, dan mengumpulkan pecahan Alatyr. Siapa tahu — suatu hari pecahannya cukup untuk mengurai jalan pulang.",
"Ясно":"Cerah",
"Переменная облачность":"Berawan sebagian",
