"Ночью духи Тени и Воды встречаются чаще, а Русалки и Навки выходят к людям.":"Di malam hari roh Bayangan dan Air lebih sering muncul, dan para Rusalka dan Navka keluar menemui manusia.",
"Новолуние":"Bulan baru",
"В безлунную ночь сияющие духи встречаются вдвое чаще.":"Di malam tanpa bulan, roh berkilau muncul dua kali lebih sering.",
