"Огненная кайма":"Tepi Api",
"Жемчужная":"Mutiara",
"Змей-уроборос":"Ular Uroboros",
"Навий шип":"Duri Nav",
"Княжий оклад":"Bingkai Bangsawan",
"Поединщик":"Duelis",
"Победи хранителей капищ":"Kalahkan penjaga Kapishche",
"Победи хранителей капищ: {0}":"Kalahkan penjaga Kapishche: {0}",
"Первый дух":"Roh pertama",
"Твои духи":"Roh-rohmu",
"Рядом появился дух — видишь светящийся круг на карте? <b>Коснись духа</b>, а потом <b>смахни оберег вверх</b>, прямо в него.":"Ada roh di dekatmu — lihat lingkaran bercahaya di peta? <b>Sentuh rohnya</b>, lalu <b>usap jimat ke atas</b>, tepat ke arahnya.",
"Второй учебный дух рядом. Кольцо вокруг духа сжимается: бросай, когда оно <b>маленькое</b>, — выйдет «Отлично!». Зелёное кольцо — дух покладистый, красное — упрямый.":"Roh latihan kedua ada di dekatmu. Cincin di sekitar roh menyusut: lempar saat cincinnya <b>kecil</b> — hasilnya “Hebat!”. Cincin hijau — roh penurut, merah — roh keras kepala.",
"Это меню — здесь все разделы. Пока открыто не всё: разделы откроются по ходу обучения, подсвеченный — следующий.":"Ini menu — semua bagian ada di sini. Belum semuanya terbuka: bagian-bagian terbuka selama tutorial, yang disorot adalah berikutnya.",
"Каждый пойманный дух — твой. Открой <b>меню</b> — золотой оберег внизу экрана.":"Setiap roh yang tertangkap adalah milikmu. Buka <b>menu</b> — jimat emas di bawah layar.",
"Это твоя коллекция — все пойманные духи. Сверху — сортировка по силе, новизне и имени и фильтр по стихиям.":"Ini koleksimu — semua roh yang kamu tangkap. Di atas ada urutan berdasarkan kekuatan, terbaru, dan nama, serta filter elemen.",
"Это разделы Ордена. Открой <b>«Духи»</b> — там твоя коллекция.":"Ini bagian-bagian Ordo. Buka <b>“Roh”</b> — di sana ada koleksimu.",
"Это карточка духа: сила, стихия, приёмы и семейство. Ниже — кнопки «Усилить» и «Превратить», а ещё можно сделать духа спутником.":"Ini kartu roh: kekuatan, elemen, jurus, dan keluarga. Di bawahnya ada tombol “Perkuat” dan “Evolusi”, dan kamu juga bisa menjadikan roh pendamping.",
"Коснись любого духа, чтобы открыть его <b>карточку</b>.":"Sentuh roh mana saja untuk membuka <b>kartunya</b>.",
"На карточке — сила духа. Нажми <b>«Усилить»</b>: за искры и эссенцию дух станет сильнее. Эссенцию приносят поимки духов того же семейства.":"Di kartu ada kekuatan roh. Tekan <b>“Perkuat”</b>: dengan percikan dan esensi roh jadi lebih kuat. Esensi didapat dari menangkap roh dari keluarga yang sama.",
"Бестиарий — все виды духов. Пойманные видны целиком, встреченные — тенью. Коснись вида, чтобы прочитать о нём.":"Bestiari — semua jenis roh. Yang sudah ditangkap terlihat utuh, yang pernah ditemui — berupa bayangan. Sentuh sebuah jenis untuk membaca tentangnya.",
"Теперь загляни в <b>«Бестиарий»</b> (меню) — там все виды духов. Сколько найдёшь ты?":"Sekarang intip <b>“Bestiari”</b> (menu) — di sana ada semua jenis roh. Berapa yang bisa kamu temukan?",
"Обереги пополняют <b>источники</b> — светящиеся чаши у памятников, фонтанов и храмов. Дойди до ближайшего джойстиком по <b>стрелке вверху</b> и коснись его. Если рядом нет — прогуляйся по карте.":"Jimat diisi ulang di <b>sumber</b> — mangkuk bercahaya di dekat monumen, air mancur, dan tempat ibadah. Pergi ke yang terdekat dengan joystick mengikuti <b>panah di atas</b>, lalu sentuh. Kalau tak ada di dekatmu, jalan-jalanlah di peta.",
"Сумка: обереги, мёд, живая вода и ладан. Сверху видно, сколько ещё поместится; лишнее можно выбросить.":"Tas: jimat, madu, Zhivaya Voda, dan dupa. Di atas terlihat sisa tempat; yang berlebih bisa dibuang.",
"Добыча уже в <b>Сумке</b>. Открой меню → «Сумка» и посмотри, что у тебя есть.":"Rampasan sudah masuk <b>Tas</b>. Buka menu → “Tas” dan lihat isinya.",
"Коконы греются шагами — одновременно можно греть три. Готовый кокон вылупится одним касанием. А твой первый дух идёт рядом — это спутник: в пути он находит эссенцию.":"Kepompong dihangatkan dengan langkah — bisa tiga sekaligus. Kepompong yang siap menetas dengan satu sentuhan. Roh pertamamu berjalan di sampingmu — itu pendampingmu: di jalan ia menemukan esensi.",
"Открой меню → <b>«Коконы»</b>. Первый кокон уже греется — пройди 2 км, и он вылупится.":"Buka menu → <b>“Kepompong”</b>. Kepompong pertama sudah dihangatkan — tempuh 2 km, dan dia akan menetas.",
"Здесь задания дня — они обновляются в полночь. А источники иногда дают поручения: выполнишь — встретишь особого духа.":"Di sini ada misi harian — diperbarui tengah malam. Sumber juga kadang memberi tugas: selesaikan, dan kamu akan bertemu roh istimewa.",
"Открой <b>«Задания»</b> — там задания дня.":"Buka <b>“Misi”</b> — di sana ada misi harian.",
"Путь Ловчего: что откроется на каждом уровне и какие награды ждут. Звания растут: Послушник, Ловчий, Следопыт, Ведун, Хранитель.":"Jalan Pemburu: apa yang terbuka di tiap level dan hadiah apa yang menanti. Gelar naik: Novis, Pemburu, Pelacak, Resi, Penjaga.",
"И последнее: открой <b>«Путь»</b> в меню — там видно, что откроется на каждом уровне Ловчего.":"Terakhir: buka <b>“Jalan”</b> di menu — di sana terlihat apa yang terbuka di tiap level Pemburu.",
"держит Капище с {0} · защитников: {1} из {2}":"menguasai Kapishche sejak {0} · pembela: {1} dari {2}",
