"Твой прогресс перенесён на другое устройство и продолжается там. На этом устройстве можно начать заново.":"Progresmu sudah dipindahkan ke perangkat lain dan berlanjut di sana. Di perangkat ini kamu bisa mulai dari awal.",
"Если ты <b>не</b> переносил прогресс — не начинай заново: напиши на почту из «Оферты» (Лавка → Казна) и укажи имя Ловчего и когда это случилось. Прогресс можно вернуть.":"Kalau kamu <b>tidak</b> memindahkan progres — jangan mulai dari awal: kirim email ke alamat di “Penawaran Publik” (Toko → Kas) dan sebutkan nama Pemburu serta kapan ini terjadi. Progres bisa dikembalikan.",
"Начать заново":"Mulai dari awal",
"Перенести прогресс сюда":"Pindahkan progres ke sini",
"На старом устройстве открой «Настройки → Перенести на другое устройство» и введи полученный код.":"Di perangkat lama buka “Pengaturan → Pindah ke perangkat lain” dan masukkan kode yang didapat.",
"Текущий прогресс на этом устройстве будет заменён.":"Progres saat ini di perangkat ini akan diganti.",
"Вводи только код со своего же устройства. Если код прислал кто-то другой — это может быть обман.":"Masukkan hanya kode dari perangkatmu sendiri. Kalau kodenya dikirim orang lain — itu bisa penipuan.",
"Перенести":"Pindahkan",
"Код — 12 букв и цифр":"Kode — 12 huruf dan angka",
"Прогресс перенесён!":"Progres dipindahkan!",
"Код переноса":"Kode pemindahan",
"Введи этот код на новом устройстве: при первом запуске — «У меня уже есть прогресс», или «Настройки → Перенести прогресс сюда». Код действует 30 минут и один раз.":"Masukkan kode ini di perangkat baru: saat pertama dibuka — “Aku sudah punya progres”, atau “Pengaturan → Pindahkan progres ke sini”. Kode berlaku 30 menit dan sekali pakai.",
"После переноса прогресс продолжится на новом устройстве, а здесь можно будет начать заново.":"Setelah dipindahkan, progres berlanjut di perangkat baru, dan di sini kamu bisa mulai dari awal.",
"<b>Никому не сообщай этот код.</b> По нему забирают весь прогресс — духов, монеты и покупки. Орден, модераторы и друзья никогда не просят код; «подарок за код» — это обман.":"<b>Jangan beri tahu kode ini ke siapa pun.</b> Dengan kode ini seluruh progres bisa diambil — roh, koin, dan pembelian. Ordo, moderator, dan teman tak pernah meminta kode; “hadiah untuk kode” itu penipuan.",
