"За день опыт идёт полностью до {0}, дальше до {1} — вполовину, сверх — на четверть. Обучение и знаки Ордена дают опыт всегда полностью. За каждый день без игры копится опыт отдыха ({2}, не больше чем за {3} {4}): пока он есть, опыт вдвое.":"Dalam sehari XP diterima penuh hingga {0}, lalu separuh hingga {1}, di atasnya — seperempat. Tutorial dan lencana Ordo selalu memberi XP penuh. Tiap hari tanpa bermain menambah XP istirahat ({2}, maks. untuk {3} {4}): selama masih ada, XP dua kali lipat.",
