"Там, где Алатырь дал трещину, из-под земли бьёт вода Перепутицы. У Источников Ловчие всех земель черпают обереги и припасы.":"Di tempat Alatyr retak, air Kekusutan Besar memancar dari tanah. Di Sumber, Pemburu dari semua negeri mengambil jimat dan perbekalan.",
