"Привяжи вход: Меню → Настройки → Учётная запись (Google, Яндекс, VK, Telegram или почта). Без этого прогресс гостя не перенесётся.":"Tautkan login: Menu → Pengaturan → Akun (Google, Yandex, VK, Telegram, atau email). Tanpa ini progres tamu tidak ikut pindah.",
